#include <bits/stdc++.h>
using namespace std;

const int N = 2e5 + 5;

vector<int> g[N];
int a[N], n, k;
int sz[N];
bool chosen[N];

void dfs_sz(int u, int p) {
    sz[u] = 1;
    for (int v : g[u]) {
        if (v == p || chosen[v]) continue;
        dfs_sz(v, u);
        sz[u] += sz[v];
    }
}

int find_centroid(int u, int p, int total) {
    for (int v : g[u]) {
        if (v == p || chosen[v]) continue;
        if (sz[v] > total / 2) return find_centroid(v, u, total);
    }
    return u;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> k;
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    // Binary search on the answer
    int lo = 1, hi = 1e6, ans = 0;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        // Check if we can get at least k nodes with a[i] >= mid in some DFS traversal
        // This is equivalent to: there exists a connected component of size >= k in the subgraph induced by nodes with a[i] >= mid
        // We need to check if the maximum connected component size in this subgraph is >= k
        // To do this efficiently, we can use a DSU-like approach or BFS/DFS
        // But since n is up to 2e5, we need an O(n) or O(n log n) check
        // Alternative: use centroid decomposition to find the maximum connected component size
        // However, a simpler approach: for each node with a[i] >= mid, count the size of its connected component
        // But this is O(n^2) in the worst case
        // Better approach: use BFS/DFS to find connected components in the subgraph induced by nodes with a[i] >= mid
        // This is O(n) per check, and binary search is O(log(1e6)), so total is O(n log(1e6)) which is acceptable

        // Reset chosen array
        for (int i = 1; i <= n; i++) chosen[i] = false;

        int max_comp = 0;
        for (int i = 1; i <= n; i++) {
            if (a[i] >= mid && !chosen[i]) {
                // BFS to find component size
                queue<int> q;
                q.push(i);
                chosen[i] = true;
                int comp_size = 0;
                while (!q.empty()) {
                    int u = q.front();
                    q.pop();
                    comp_size++;
                    for (int v : g[u]) {
                        if (a[v] >= mid && !chosen[v]) {
                            chosen[v] = true;
                            q.push(v);
                        }
                    }
                }
                max_comp = max(max_comp, comp_size);
            }
        }

        if (max_comp >= k) {
            ans = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }

    cout << ans << endl;
    return 0;
}
