#include <bits/stdc++.h>
using namespace std;

const int N = 2e5 + 5;

int n, k;
int a[N];
vector<int> g[N];

int sz[N];
bool vis[N];

void dfs_sz(int u, int p) {
    sz[u] = 1;
    for (int v : g[u]) {
        if (v == p || vis[v]) continue;
        dfs_sz(v, u);
        sz[u] += sz[v];
    }
}

int find_centroid(int u, int p, int total) {
    for (int v : g[u]) {
        if (v == p || vis[v]) continue;
        if (sz[v] > total / 2) return find_centroid(v, u, total);
    }
    return u;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> k;
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    int ans = 0;
    function<void(int, int)> decompose = [&](int u, int p) {
        dfs_sz(u, p);
        int c = find_centroid(u, p, sz[u]);
        vis[c] = true;

        vector<int> children;
        for (int v : g[c]) {
            if (vis[v]) continue;
            children.push_back(v);
        }

        sort(children.begin(), children.end(), [&](int x, int y) {
            return a[x] > a[y];
        });

        int rem = k - 1;
        for (int v : children) {
            if (rem <= 0) break;
            dfs_sz(v, c);
            int take = min(rem, sz[v]);
            rem -= take;
        }

        if (rem <= 0) {
            ans = max(ans, a[c]);
        }

        for (int v : children) {
            if (!vis[v]) decompose(v, c);
        }
    };

    decompose(1, 0);
    cout << ans << endl;
    return 0;
}
