    vector<int> sz(n + 1, 0);
    vector<bool> vis(n + 1, false);
    function<void(int, int)> dfs = [&](int u, int p) {
        sz[u] = 1;
        for (int v : g[u]) {
            if (v == p || vis[v]) continue;
            dfs(v, u);
            sz[u] += sz[v];
        }
    };

    function<bool(int, int, int)> check = [&](int u, int p, int rem) {
        if (a[u] < x) return false;
        vis[u] = true;
        vector<int> children;
        for (int v : g[u]) {
            if (v == p || vis[v]) continue;
            children.push_back(v);
        }
        sort(children.begin(), children.end(), [&](int A, int B) {
            return sz[A] > sz[B];
        });
        for (int v : children) {
            if (rem <= 0) break;
            if (a[v] < x) continue;
            dfs(v, u);
            if (sz[v] >= rem) {
                if (check(v, u, rem)) return true;
            } else {
                rem -= sz[v];
                vis[v] = true;
            }
        }
        vis[u] = false;
        return rem <= 0;
    };

    vector<int> roots;
    for (int i = 1; i <= n; i++) {
        if (a[i] >= x) roots.push_back(i);
    }
    for (int r : roots) {
        fill(vis.begin(), vis.end(), false);
        dfs(r, -1);
        fill(vis.begin(), vis.end(), false);
        if (check(r, -1, k)) return true;
    }
    return false;
};

