#include <bits/stdc++.h>
using namespace std;

const int N = 2e5 + 5;

vector<int> g[N];
int a[N], n, k;
int sz[N];
bool bad;

void dfs_sz(int u, int p) {
    sz[u] = 1;
    for (int v : g[u]) {
        if (v == p) continue;
        dfs_sz(v, u);
        sz[u] += sz[v];
    }
}

int find_centroid(int u, int p, int total) {
    for (int v : g[u]) {
        if (v == p) continue;
        if (sz[v] > total / 2) return find_centroid(v, u, total);
    }
    return u;
}

void dfs_check(int u, int p, int limit) {
    if (a[u] < limit) {
        bad = true;
        return;
    }
    for (int v : g[u]) {
        if (v == p) continue;
        dfs_check(v, u, limit);
        if (bad) return;
    }
}

bool check(int limit) {
    bad = false;
    dfs_check(1, -1, limit);
    if (bad) return false;
    dfs_sz(1, -1);
    int c = find_centroid(1, -1, n);
    vector<int> sizes;
    for (int v : g[c]) {
        sizes.push_back(sz[v]);
    }
    sort(sizes.rbegin(), sizes.rend());
    int sum = 1;
    for (int s : sizes) {
        sum += s;
        if (sum >= k) return true;
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> k;
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    int lo = 1, hi = 1e6 + 1;
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (check(mid)) lo = mid;
        else hi = mid - 1;
    }
    cout << lo << endl;
    return 0;
}
